from flask import Flask, request, abort

app = Flask(__name__)

@app.route('/compute')
def compute():
    try:
        # Get the iterations parameter and default to 1000 if not provided
        iterations = int(request.args.get('iterations', '1000'))
    except ValueError:
        return "Invalid input: iterations must be an integer", 400

    # Limit the maximum number of iterations to 10,000
    max_iterations = 10000
    if iterations < 1 or iterations > max_iterations:
        return f"Iterations must be between 1 and {max_iterations}", 400

    result = 0
    for i in range(iterations):
        result += i * i

    return f"Computed sum of squares: {result}"

