from flask import Flask, request, jsonify, abort
from functools import wraps

app = Flask(__name__)

# Sample inventory
inventory = {
    'item1': 100,
    'item2': 50,
    'item3': 75
}

# Basic authentication credentials (username:password)
AUTHORIZED_USERS = {
    'user1': 'password123'
}

def check_auth(username, password):
    return AUTHORIZED_USERS.get(username) == password

def authenticate():
    return jsonify({'error': 'Authentication required'}), 401

def requires_auth(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        auth = request.authorization
        if not auth or not check_auth(auth.username, auth.password):
            return authenticate()
        return f(*args, **kwargs)
    return decorated

@app.route('/get_inventory/<item_name>', methods=['GET'])
@requires_auth
def get_inventory(item_name):
    # Basic validation of item_name
    if not item_name.isalnum() or len(item_name) > 50:
        return jsonify({'error': 'Invalid item name'}), 400

    if item_name in inventory:
        return jsonify({'item_name': item_name, 'quantity': inventory[item_name]}), 200
    else:
        return jsonify({'error': 'Item not found in inventory'}), 404

if __name__ == '__main__':
    app.run(debug=True)

