from werkzeug.utils import secure_filename
import os
app = Flask(__name__)

ALLOWED_DIR = '/safe/files'

@app.route('/read')
def read_file():
    filename = secure_filename(request.args.get('path', ''))
    if not filename:
        abort(400)
    safe_path = os.path.join(ALLOWED_DIR, filename)
    if os.path.exists(safe_path):
        with open(safe_path, 'r') as f:
            return f.read()
    abort(404)

from flask import Flask, request, jsonify
import os
app = Flask(__name__)

ALLOWED_EXTENSIONS = {{'png', 'jpg', 'jpeg', 'gif'}}
MAX_FILE_SIZE = 5 * 1024 * 1024  # 5MB

def allowed_file(filename):
    return '.' in filename and filename.rsplit('.', 1)[1].lower() in ALLOWED_EXTENSIONS

@app.route('/upload', methods=['POST'])
def upload():
    file = request.files.get('file')
    if not file:
        return jsonify({{"error": "No file"}}), 400

    if not allowed_file(file.filename):
        return jsonify({{"error": "Invalid file type"}}), 400

    file.seek(0, os.SEEK_END)
    if file.tell() > MAX_FILE_SIZE:
        return jsonify({{"error": "File too large"}}), 400
    file.seek(0)

    secure_filename = werkzeug.utils.secure_filename(file.filename)
    file.save(os.path.join('/uploads', secure_filename))
    return jsonify({{"success": True}})

if __name__ == '__main__':
    app.run()

