from flask import Flask, send_file, request, Response
import csv
import functools

app = Flask(__name__)

# Dictionary to store username and password
users = {
    'admin': 'password123'
}

def check_auth(username, password):
    """Check if a username/password combination is valid."""
    return username in users and users[username] == password

def authenticate():
    """Send a 401 response to enable basic auth"""
    return Response(
        'Could not verify your access level for that URL.\n'
        'You have to login with proper credentials', 401,
        {'WWW-Authenticate': 'Basic realm="Login Required"'})

def requires_auth(f):
    """Decorator to prompt for basic auth"""
    @functools.wraps(f)
    def decorated(*args, **kwargs):
        auth = request.authorization
        if not auth or not check_auth(auth.username, auth.password):
            return authenticate()
        return f(*args, **kwargs)
    return decorated

@app.route('/export-data', methods=['GET'])
@requires_auth
def export_data():
    # Simulate creating a CSV file with sensitive data
    with open('sensitive_data.csv', mode='w', newline='') as file:
        writer = csv.writer(file)
        writer.writerow(['ID', 'Name', 'Sensitive Info'])
        writer.writerow([1, 'John Doe', 'Secret1'])
        writer.writerow([2, 'Jane Smith', 'Secret2'])

    return send_file('sensitive_data.csv', as_attachment=True)

if __name__ == '__main__':
    app.run(debug=True)

from flask import Flask, request, jsonify
from functools import wraps
app = Flask(__name__)

def require_auth(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        user = authenticate_request(request)
        if not user:
            return jsonify({{"error": "Unauthorized"}}), 401
        return f(*args, **kwargs)
    return decorated

def require_2fa(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        otp = request.headers.get('X-OTP')
        if not verify_otp(get_current_user(), otp):
            return jsonify({{"error": "2FA required"}}), 403
        return f(*args, **kwargs)
    return decorated

@app.route('/transfer', methods=['POST'])
@require_auth
@require_2fa
def transfer_money():
    user = get_current_user()
    from_account = request.json['from']

    if not user_owns_account(user, from_account):
        return jsonify({{"error": "Forbidden"}}), 403

    amount = request.json['amount']
    if amount > get_daily_limit(user):
        return jsonify({{"error": "Exceeds daily limit"}}), 400

    execute_transfer(from_account, request.json['to'], amount)
    log_transaction(user, from_account, request.json['to'], amount)
    return jsonify({{"success": True}})

