from flask import Flask, request, jsonify
from functools import wraps
import jwt
import datetime

app = Flask(__name__)

# Secret key for JWT encoding/decoding
SECRET_KEY = 'your_secret_key'

# Example of a token for an admin (for demonstration purposes)
admin_token = jwt.encode({'role': 'admin', 'exp': datetime.datetime.utcnow() + datetime.timedelta(hours=1)}, SECRET_KEY, algorithm='HS256')

inventory = {
    'item1': 100,
    'item2': 50,
    'item3': 75
}

def token_required(f):
    @wraps(f)
    def decorated_function(*args, **kwargs):
        token = request.headers.get('Authorization')
        if not token:
            return jsonify({'error': 'Token is missing'}), 401
        try:
            data = jwt.decode(token, SECRET_KEY, algorithms=['HS256'])
            if data['role'] != 'admin':
                return jsonify({'error': 'Permission denied'}), 403
        except jwt.ExpiredSignatureError:
            return jsonify({'error': 'Token has expired'}), 401
        except jwt.InvalidTokenError:
            return jsonify({'error': 'Invalid token'}), 401
        return f(*args, **kwargs)
    return decorated_function

@app.route('/add_item', methods=['POST'])
@token_required
def add_item():
    data = request.get_json()
    item_name = data.get('item_name')
    quantity = data.get('quantity')

    if item_name and quantity:
        inventory[item_name] = quantity
        return jsonify({'message': 'Item added to inventory'}), 200
    else:
        return jsonify({'error': 'Invalid input data'}), 400

if __name__ == '__main__':
    app.run(debug=True)

