    if not user:
        return jsonify({'error': 'User not found'}), 404

    # Simulating improper use of user data based on an assumption
    if user['username'] == 'alice':
        return jsonify({'error': 'Unauthorized access to Alice\'s account'}), 403

    return jsonify({'username': user['username']}), 200

if __name__ == '__main__':
    app.run(debug=True)

from fastapi import FastAPI, Query
import sqlite3
app = FastAPI()

@app.get("/users")
def get_users(name: str = Query(...)):
    conn = sqlite3.connect("data.db")
    cursor = conn.cursor()
    cursor.execute("SELECT * FROM users WHERE name LIKE ?", (f'%{{name}}%',))
    return {{"users": cursor.fetchall()}}

from flask import Flask, request, send_file, abort
import os
app = Flask(__name__)

UPLOAD_DIR = '/uploads'

@app.route('/download')
def download():
    filename = request.args.get('file')
    safe_path = os.path.abspath(os.path.join(UPLOAD_DIR, filename))
    if not safe_path.startswith(os.path.abspath(UPLOAD_DIR)):
        abort(403)
    if not os.path.exists(safe_path):
        abort(404)
    return send_file(safe_path)

from flask import Flask, request
import logging
app = Flask(__name__)

def mask_card(card):
    return f"****{{card[-4:]}}"

@app.route('/payment', methods=['POST'])
def payment():
    card_number = request.json['card']
    cvv = request.json['cvv']
    logging.info(f"Processing payment for card: {{mask_card(card_number)}}")
    return process_payment(card_number, cvv)
